with stage_rows as ( select ms.workflow_id, ms.stage_number, ms.stage_type, ms.status, ms.started_at, ms.completed_at, ms.error_message from mission_stages ms where ms.workflow_id = 'c8e34eac-bc1a-44d8-a795-0063092422be' ), newer_rows as ( select wi.workflow_id, wi.session_id, wi.status, wi.started_at, wi.completed_at, wi.error, wi.input_data->>'processing_profile' as processing_profile from workflow_instances wi where wi.session_id = '68de23b2-9fcc-47bb-ab60-66f1044dce10' and wi.started_at > timestamp with time zone '2026-04-20 13:58:50+00' order by wi.started_at ) select concat('STAGE | workflow_id=', workflow_id, ' | stage_number=', coalesce(stage_number::text,''), ' | stage_type=', coalesce(stage_type,''), ' | status=', coalesce(status,''), ' | started_at=', coalesce(to_char(started_at,'YYYY-MM-DD HH24:MI:SSOF'),''), ' | completed_at=', coalesce(to_char(completed_at,'YYYY-MM-DD HH24:MI:SSOF'),''), ' | error=', coalesce(replace(error_message,E'\n',' '),'')) from stage_rows union all select concat('NEWER | workflow_id=', workflow_id, ' | session_id=', session_id, ' | status=', coalesce(status,''), ' | started_at=', coalesce(to_char(started_at,'YYYY-MM-DD HH24:MI:SSOF'),''), ' | completed_at=', coalesce(to_char(completed_at,'YYYY-MM-DD HH24:MI:SSOF'),''), ' | error=', coalesce(replace(error,E'\n',' '),''), ' | processing_profile=', coalesce(processing_profile,'')) from newer_rows;
